const n = (count: string, one: string, many: string) => `${count} ${count === '0' || count === '1' ? one : many}`;

/** Phrases with a number or a name in them. */
export const FR_PATTERNS: Language['patterns'] = [
  [/^Importing (.+)$/, (m) => `Import de ${m[1]}`],
  [/^Linking (.+)$/, (m) => `Liaison de ${m[1]}`],
  [/^Reading (.+\.ifc)$/i, (m) => `Lecture de ${m[1]}`],
  [/^(.+) — ([^·]+?)(?: · (.+))?$/, (m) => `${FR[m[1]] ?? m[1]} — ${m[2]}${m[3] ? ` · ${FR[m[3]] ?? m[3]}` : ''}`],
  [/^(Fold|Unfold) the (project browser|properties)(?: \((.+)\))?$/, (m) => `${m[1] === 'Fold' ? 'Replier' : 'Déplier'} ${m[2] === 'properties' ? 'les propriétés' : 'l’arborescence du projet'}${m[3] ? ` (${m[3]})` : ''}`],
  [/^Keep the (project browser|properties) open(?: \((.+)\))?$/, (m) => `Garder ${m[1] === 'properties' ? 'les propriétés ouvertes' : 'l’arborescence du projet ouverte'}${m[2] ? ` (${m[2]})` : ''}`],
  [/^Quick tool (\d)$/, (m) => `Outil rapide ${m[1]}`],
  [/^Object snap \((.+)\)$/, (m) => `Accrochage aux objets (${m[1]})`],
  [/^Ortho \((.+); hold Shift\)$/, (m) => `Ortho (${m[1]} ; maintenir Maj)`],
  [/^Polar tracking every 45° \((.+)\)$/, (m) => `Repérage polaire tous les 45° (${m[1]})`],
  [/^Reassign to (.+)$/, (m) => `Réaffecter à ${FR[m[1]] ?? m[1]}`],
  [/^Also used by (.+)$/, (m) => `Également utilisé par ${m[1]}`],
  [/^In (.+)'s session, to look$/, (m) => `Dans la session de ${m[1]}, en observateur`],
  [/^In (.+)'s session$/, (m) => `Dans la session de ${m[1]}`],
  [/^(.+) is in this plan\.$/, (m) => `${m[1]} est dans ce plan.`],
  [/^(.+) is in 3D\.$/, (m) => `${m[1]} est en 3D.`],
  [/^Undo „(.+)”: (.+) changed it after you; it is left as it is\.$/, (m) => `Annuler « ${m[1]} » : ${m[2] === 'Someone' ? 'quelqu’un d’autre' : m[2]} l’a modifié après vous ; il est laissé tel quel.`],
  [/^Redo „(.+)”: (.+) changed it after you; it is left as it is\.$/, (m) => `Rétablir « ${m[1]} » : ${m[2] === 'Someone' ? 'quelqu’un d’autre' : m[2]} l’a modifié après vous ; il est laissé tel quel.`],
  [/^Segment (\d+) \((m|°|ratio)\)$/, (m) => `Segment ${m[1]} (${m[2] === 'ratio' ? 'proportion' : m[2]})`],
  [/^(aligned|linear) · (\d+) segments$/, (m) => `${m[1] === 'aligned' ? 'alignée' : 'linéaire'} · ${m[2]} segments`],
  [/^(\d+) elements?$/, (m) => n(m[1], 'élément', 'éléments')],
  [/^(\d+) of (\d+) storeys$/, (m) => `${m[1]} sur ${m[2]} niveaux`],
  [/^cut at (.+) m$/, (m) => `coupé à ${m[1]} m`],
  [/^Underlay: (.+)$/, (m) => `Calque de fond : ${m[1]}`],
  [/^(\d+) (survey points|feature\(s\)|building\(s\)) imported, in the project's coordinates \(Manage → Location shows its system and survey point\)\.$/, (m) => `${m[1]} ${({ 'survey points': 'point(s) topographique(s)', 'feature(s)': 'élément(s)', 'building(s)': 'bâtiment(s)' } as Record<string, string>)[m[2]]} importé(s), dans les coordonnées du projet (Gérer → Emplacement montre son système et son point topographique).`],
  [/^(\d+) to check$/, (m) => `${m[1]} à vérifier`],
  [/^Plan · (.+)$/, (m) => `Plan · ${m[1]}`],
  [/^(\d+) line edit\(s\) lost their edge · clean$/, (m) => `${n(m[1], 'modification de ligne a perdu son arête', 'modifications de ligne ont perdu leur arête')} · nettoyer`],
  [/^view range: (\d+) problem\(s\)$/, (m) => `plage de vue : ${n(m[1], 'problème', 'problèmes')}`],
  [/^(.+) · (\d+) selected$/, (m) => `${m[1]} · ${n(m[2], 'sélectionné', 'sélectionnés')}`],
  [/^Camera at (.+) m: drag$/, (m) => `Caméra à ${m[1]} m : faites glisser`],
  [/^(Key plan|On screen|Seen from|Cut at) · (.+)$/, (m) => `${({ 'Key plan': 'Plan de repérage', 'On screen': 'À l’écran', 'Seen from': 'Vu depuis', 'Cut at': 'Coupé à' } as Record<string, string>)[m[1]]} · ${m[2]}`],
  [/^Terrain created from (\d+) points\.$/, (m) => `Terrain créé à partir de ${n(m[1], 'point', 'points')}.`],
  [/^(\d+) element\(s\) moved to (.+)\.$/, (m) => `${n(m[1], 'élément déplacé', 'éléments déplacés')} vers ${m[2]}.`],
  [/^(\d+) element\(s\) selected, now on (.+)\.$/, (m) => `${n(m[1], 'élément sélectionné', 'éléments sélectionnés')}, désormais sur ${m[2]}.`],
  [/^Type parameters · (.+)$/, (m) => `Paramètres de type · ${m[1]}`],
  [/^(\d+) bays along × (\d+) up · IFC: (.+)$/, (m) => `${m[1]} trames en longueur × ${m[2]} en hauteur · IFC : ${m[3]}`],
  [/^(\d+) value\(s\) added\.$/, (m) => `${n(m[1], 'valeur ajoutée', 'valeurs ajoutées')}.`],
  [/^(\d+) room\(s\) updated\.$/, (m) => `${n(m[1], 'pièce mise à jour', 'pièces mises à jour')}.`],
  [/^IFC properties · (\d+)$/, (m) => `Propriétés IFC · ${m[1]}`],
  [/^(.+) could not be read as a picture: attach a PNG or JPEG screenshot \(or send the report without one\)\.$/, (m) => `${m[1]} n’a pas pu être lu comme une image : joignez une capture d’écran PNG ou JPEG (ou envoyez le rapport sans).`],
  [/^(\d+) room\(s\) updated; (\d+) no longer enclosed \(they keep their last outline\)\.$/, (m) => `${n(m[1], 'pièce mise à jour', 'pièces mises à jour')} ; ${n(m[2], 'n’est plus fermée', 'ne sont plus fermées')} (elles gardent leur dernier contour).`],
  [/^No room has a value for this field yet\. Give rooms a (.+) in their properties\.$/, (m) => `Aucune pièce n’a encore de valeur pour ce champ. Donnez aux pièces une valeur (${m[1]}) dans leurs propriétés.`],
  // The model assistant's lines: its steps, its tables, what it applied
  [/^Listed (\d+) of (\d+) · (.+)$/, (m) => `A listé ${m[1]} sur ${m[2]} · ${m[3] === 'all' ? 'tous' : m[3]}`],
  [/^Computed (\d+) group\(s\) over (\d+) element\(s\)$/, (m) => `A calculé ${n(m[1], 'groupe', 'groupes')} sur ${n(m[2], 'élément', 'éléments')}`],
  [/^Read element (.+)$/, (m) => `A lu l’élément ${m[1]}`],
  [/^Read schedule (.+)$/, (m) => `A lu la nomenclature ${m[1]}`],
  [/^Proposed (\d+) change\(s\)$/, (m) => `A proposé ${n(m[1], 'modification', 'modifications')}`],
  [/^Proposed (\d+) change\(s\), (\d+) refused$/, (m) => `A proposé ${n(m[1], 'modification', 'modifications')}, ${n(m[2], 'refusée', 'refusées')}`],
  [/^Tool failed: (.+)$/, (m) => `L’outil a échoué : ${m[1]}`],
  [/^(\d+) row\(s\)$/, (m) => n(m[1], 'ligne', 'lignes')],
  [/^(\d+) value\(s\) applied: one step to undo\.$/, (m) => `${n(m[1], 'valeur appliquée', 'valeurs appliquées')} : une seule étape à annuler.`],
  [/^Grouped by (.+)$/, (m) => `Groupé par ${m[1]}`],
  [/^(\d+) of (\d+) ticked$/, (m) => `${m[1]} sur ${m[2]} cochés`],
  // The undo buttons' tooltips: "Undo Move (Ctrl+Z)", "Redo (Ctrl+Y, Ctrl+Shift+Z)"
  [/^(Undo|Redo) \(([^()]+)\)$/, (m) => `${m[1] === 'Undo' ? 'Annuler' : 'Rétablir'} (${m[2]})`],
  [/^(Undo|Redo) (.+?)(?: \(([^()]+)\))?$/, (m) => `${m[1] === 'Undo' ? 'Annuler' : 'Rétablir'} ${FR[m[2]] ?? m[2]}${m[3] ? ` (${m[3]})` : ''}`],
];
